CREATE OR REPLACE VIEW `vwcoge` AS select date_format(`p`.`erogated_at`,'%Y-%m') AS `mese`,count(0) AS `n`,sum((if((`p`.`entrata_uscita` = 'Entrata'),1,0) * `p`.`importo`)) AS `entrata`,sum((if((`p`.`entrata_uscita` = 'Entrata'),0,1) * `p`.`importo`)) AS `uscita`,0 AS `storno_entrata`,0 AS `storno_uscita` from `provvigioni` `p` where (`p`.`erogated_at` is not null) group by date_format(`p`.`erogated_at`,'%Y-%m') order by date_format(`p`.`erogated_at`,'%Y-%m') desc
